result.args:
位置参数数组：[input: {
    /** 远程资源使用已发布的固定 URI 句柄，包内资源使用当前文档的 rN 句柄；不接受来源描述对象或本地文件路径。 */
    resource: ResourceHandle;
    /** 实例根要挂接的父节点身份；显式 null 放在场景根，不能传数字 parentId。 */
    parent: NodeHandle | null;
    /** 可选实例根展示名；普通模型省略时使用 Model。UI 实例根始终使用资源 payload 的 uiId，若显式传 name，必须与 uiId 完全一致，否则拒绝；通过 instantiateModel 装配 UI 资源时也遵守此规则。 */
    name?: string;
}]
args[0] input: 已发布 URI 或当前包内模型句柄、显式父级和可选展示名；普通模型默认名为 Model，若资源为 UI 则遵守 UI 命名规则。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。
ResourceHandle：资源来源身份；远程值为固定 URI，包内值为 r12，直接来自当前文档 resourceRefs 中的 ID。

result.returns:
{
    /** 成功操作后的模型或 UI 根节点身份；用该句柄继续查询和编辑，不自行猜测 Runtime 数字 ID。 */
    root: NodeHandle;
}
